func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<4x8xf32>

  // Create zero constant for reduce init
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c0_0 = stablehlo.broadcast_in_dim %c0 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<>  // rank-0 tensor

  // Reduce sum over dimension 1 (columns) of exp_x, result shape: tensor<4xf32>
  %sum_exp = "stablehlo.reduce"(%exp_x, %c0_0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4xf32>

  // Broadcast sum_exp back to shape 4x8 for division
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0} : (tensor<4xf32>) -> tensor<4x8xf32>

  // Divide exp_x by sum_exp_bcast to get softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_bcast : tensor<4x8xf32>

  "stablehlo.return"(%softmax) : tensor<4x8xf32>
}
