func.func @main(%arg0: tensor<f32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = constant scalar tensor<f32> (parameter `constant`)
  // %arg1 = linear.weight tensor<7x7xf32>
  // %arg2 = linear.bias tensor<7xf32>
  // %arg3 = input tensor<6x7xf32>

  // Perform linear layer: x @ W^T + b
  // Note: PyTorch Linear weight shape is (out_features, in_features) = (7,7)
  // Input shape: (6,7)
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight is (7,7), so to do x @ W^T, we transpose weight to (7,7)
  // Actually, since weight is square, transpose is the same shape, but we must transpose to get correct multiplication:
  // x: (6,7), W: (7,7)
  // PyTorch linear does x @ W^T + b, so we transpose weight.

  %w_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // dot_general: batch dims empty, contracting dims: lhs dim 1, rhs dim 0
  %dot = "stablehlo.dot_general"(%arg3, %w_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: %arg2 shape is (7), need to broadcast to (6,7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Apply minimum with constant scalar %arg0
  // Broadcast constant scalar to (6,7)
  %const_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7xf32>

  %min_out = stablehlo.minimum %linear_out, %const_broadcast : tensor<6x7xf32>

  // Subtract constant scalar broadcasted
  %result = stablehlo.subtract %min_out, %const_broadcast : tensor<6x7xf32>

  return %result : tensor<6x7xf32>
}
