  %c_scale_bcast = "stablehlo.broadcast_in_dim"(%c_scale) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %t4 = stablehlo.multiply %t3, %c_scale_bcast : tensor<6x1xf32>
