func.func @main(%idx: tensor<5xi32>) -> tensor<5x8xf32> {
  %c8 = "stablehlo.constant"() {value = dense<8> : tensor<i32>} : () -> tensor<i32>
  %c1f = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %c0f = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Create iota for channel dimension: shape (8)
  %iota_c = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx from (5) to (5x8) with broadcast_dimensions = [0]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast iota_c from (8) to (5x8) with broadcast_dimensions = [1]
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota_c) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_bcast == iota_bcast -> (5x8xi1)
  %cmp_eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Check idx in [0,7]: idx >= 0 and idx < 8
  %c0 = "stablehlo.constant"() {value = dense<0> : tensor<i32>} : () -> tensor<i32>
  %cmp_ge0 = "stablehlo.compare"(%idx, %c0) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
  %cmp_lt8 = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>

  // idx_in_range = cmp_ge0 AND cmp_lt8
  %idx_in_range = "stablehlo.and"(%cmp_ge0, %cmp_lt8) : (tensor<5xi1>, tensor<5xi1>) -> tensor<5xi1>

  // Broadcast idx_in_range from (5) to (5x8) with broadcast_dimensions = [0]
  %idx_in_range_bcast = "stablehlo.broadcast_in_dim"(%idx_in_range) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Select: if cmp_eq and idx_in_range_bcast then 1.0 else 0.0
  %pred = "stablehlo.and"(%cmp_eq, %idx_in_range_bcast) : (tensor<5x8xi1>, tensor<5x8xi1>) -> tensor<5x8xi1>
  %out = "stablehlo.select"(%pred, %c1f, %c0f) : (tensor<5x8xi1>, tensor<f32>, tensor<f32>) -> tensor<5x8xf32>

  return %out : tensor<5x8xf32>
}
