func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %gemm = input @ weight^T + bias
  // dot_general with contracting dims: input dim 1 and weight dim 1 (weight is 7x7, so transpose weight dims)
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %gemm = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %gemm_bias = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias_added = stablehlo.add %gemm, %gemm_bias : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // mean = reduce mean over batch dim 0 (dim=0)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%gemm_bias_added, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %batch_size = stablehlo.constant dense<6.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %batch_size : tensor<7xf32>

  // variance = reduce mean of (x - mean)^2 over batch dim 0
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %gemm_bias_added, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_zero_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_zero_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %variance = stablehlo.divide %var_sum, %batch_size : tensor<7xf32>

  // epsilon constant for batchnorm
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>

  // variance + epsilon
  %var_eps = stablehlo.add %variance, %epsilon : tensor<7xf32>

  // rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // normalize: (x - mean) * inv_std
  %diff_norm = stablehlo.multiply %diff, "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // scale and shift: bn_weight * normalized + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %diff_norm, %bn_weight_broadcast : tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // multiply by scale parameter (broadcast scale from [1] to [6,7])
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_out = stablehlo.multiply %bn_out, %scale_broadcast : tensor<6x7xf32>

  // softmax along dim=1 (features dimension)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // compute max along dim=1 (dim=1)
  %init_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%scaled_out, %init_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast max to shape [6,7]
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // x - max
  %shifted = stablehlo.subtract %scaled_out, %max_broadcast : tensor<6x7xf32>
  // exp(x - max)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>
  // sum exp along dim=1
  %init_zero_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast sum_exp to [6,7]
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // divide exp by sum_exp
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_broadcast : tensor<6x7xf32>

  "stablehlo.return"(%softmax) : tensor<6x7xf32>
}
