func.func @main(%bias: tensor<1x1x1x1xf32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
  // Step 1: Perform ConvTranspose3d (transposed convolution)
  // conv_transpose_weight shape: [in_channels=3, out_channels=16, kD=3, kH=3, kW=3]
  // StableHLO convolution expects kernel shape: [out_channels, in_channels, kD, kH, kW]
  // So we need to transpose conv_transpose_weight from [3,16,3,3,3] to [16,3,3,3,3]
  %weight_reshaped = "stablehlo.reshape"(%conv_transpose_weight) : (tensor<3x16x3x3x3xf32>) -> tensor<3x16x27xf32>
  %weight_transposed = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // The input shape is [6,3,16,7,7]
  // ConvTranspose3d parameters:
  // stride=2, padding=1
  // dimension_numbers: input [b, f, d, h, w], kernel [o, i, kd, kh, kw], output [b, f, d, h, w]
  // lhs_dilation = stride (for transposed conv)
  // rhs_dilation = 1
  // padding = 1
  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3, 4]x[o, i, 2, 3, 4]->[b, f, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Add conv_transpose_bias (shape [16]) to conv output (broadcast over batch and spatial dims)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<6x16x31x13x13xf32>
  %conv_biased = stablehlo.add %conv, %bias_broadcast : tensor<6x16x31x13x13xf32>

  // Step 2: logsumexp over dim=1 (channel dimension), keepdim=True
  // logsumexp(x) = log(sum(exp(x)))
  // Compute exp(x)
  %exp_conv = stablehlo.exponential %conv_biased : tensor<6x16x31x13x13xf32>

  // Create init value 0 for sum reduce
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_scalar = "stablehlo.reshape"(%zero) : (tensor<f32>) -> tensor<> // rank-0 tensor

  // Reduce sum over dim=1
  %sum_exp = "stablehlo.reduce"(%exp_conv, %zero_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x31x13x13xf32>

  // Reshape sum_exp to keep dim=1 as size 1 (for keepdim=True)
  %sum_exp_reshaped = "stablehlo.reshape"(%sum_exp) : (tensor<6x31x13x13xf32>) -> tensor<6x1x31x13x13xf32>

  // Compute log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp_reshaped : tensor<6x1x31x13x13xf32>

  // Step 3: HardSwish: x * sigmoid(x + 3) / 6
  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %x_plus_3 = stablehlo.add %log_sum_exp, %three_broadcast : tensor<6x1x31x13x13xf32>

  // Compute sigmoid(x + 3) = 1 / (1 + exp(-x))
  %neg_x_plus_3 = stablehlo.negate %x_plus_3 : tensor<6x1x31x13x13xf32>
  %exp_neg = stablehlo.exponential %neg_x_plus_3 : tensor<6x1x31x13x13xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %denominator = stablehlo.add %one_broadcast, %exp_neg : tensor<6x1x31x13x13xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denominator : tensor<6x1x31x13x13xf32>

  // Multiply x * sigmoid(x + 3)
  %mul = stablehlo.multiply %log_sum_exp, %sigmoid : tensor<6x1x31x13x13xf32>

  // Divide by 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %hard_swish = stablehlo.divide %mul, %six_broadcast : tensor<6x1x31x13x13xf32>

  // Step 4: Subtract bias (shape [1x1x1x1]) broadcasted to output shape
  %bias_broadcast_out = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<1x1x1x1xf32>) -> tensor<6x1x31x13x13xf32>
  %sub = stablehlo.subtract %hard_swish, %bias_broadcast_out : tensor<6x1x31x13x13xf32>

  // Step 5: Clamp between -1 and 1
  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = "stablehlo.broadcast_in_dim"(%neg_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %one_broadcast2 = %one_broadcast
  %max_clamped = stablehlo.maximum %sub, %neg_one_broadcast : tensor<6x1x31x13x13xf32>
  %clamped = stablehlo.minimum %max_clamped, %one_broadcast2 : tensor<6x1x31x13x13xf32>

  // Return final result
  return %clamped : tensor<6x1x31x13x13xf32>
}
