  // gelu activation: gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>  // approximate sqrt(2)

  // x / sqrt(2)
  %x_div_sqrt2 = stablehlo.divide %avg_pool_squeezed2, %sqrt2 : tensor<16xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<16xf32>

  // 1 + erf(...)
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<16xf32>

