  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %half_x = stablehlo.multiply %half_broadcast, %avg_pool_squeezed2 : tensor<16xf32>

  // gelu = 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<16xf32>

  // scale by scale_factor = 2.0
  %scale_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_factor_broadcast = "stablehlo.broadcast_in_dim"(%scale_factor) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %scaled = stablehlo.multiply %gelu, %scale_factor_broadcast : tensor<16xf32>

  // max over dim=1 (features dimension)
  // input shape: (16) but we need to max over dim=1, so input must be 2D
  // Actually, after avg_pool and gelu and scale, shape is (16), which is batch dimension only
  // But original input was (batch=16, features=16)
  // The PyTorch code does torch.max(x, dim=1).values on the scaled tensor of shape (batch, out_features)
  // After avg_pool with kernel=16, features dimension is reduced to 1, so output shape is (batch=16)
  // So max over dim=1 is just the value itself
  // But we must implement max over dim=1 anyway

  // reshape to (16x1)
