  // reduce max over dim=1
  %init_min = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%scaled_reshaped, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<16x1xf32>, tensor<f32>) -> tensor<16xf32>

  stablehlo.return %max : tensor<16xf32>
}

