  %c121 = stablehlo.constant dense<121.0> : tensor<f32>
  %c121_broadcast = "stablehlo.broadcast_in_dim"(%c121) {broadcast_dimensions = array<i64: 3>} : (tensor<f32>) -> tensor<16x16x1x1xf32>
  %result = stablehlo.divide %r2, %c121_broadcast : tensor<16x16x1x1xf32>

  return %result : tensor<16x16x1x1xf32>
}
