  %kernel_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<6x7x5x5x5xf32>) -> tensor<7x6x5x5x5xf32>

  // Set convolution parameters for transposed conv:
  // lhs_dilation = stride = [2,2,2]
  // rhs_dilation = [1,1,1]
  // padding = [kernel_size - 1 - padding] = [5-1-2=2] on each side
  // window_strides = [1,1,1] (for transposed conv, stride is lhs_dilation)
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  // feature_group_count = 1
  // batch_group_count = 1

  %conv = "stablehlo.convolution"(%arg2, %kernel_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
