      stablehlo.return %s : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<16x7x1x1x1xf32>, tensor<f32>) -> tensor<16x1x1x1xf32>

  // Add back the reduced dimension as size 1 to get [16x1x1x1x1]
  %sum_reshaped = stablehlo.reshape %sum : (tensor<16x1x1x1xf32>) -> tensor<16x1x1x1x1xf32>

  stablehlo.return %sum_

