  // lhs_dilation = stride = [2,2,2]
  // rhs_dilation = [1,1,1]
  // padding = [kernel_size - 1 - padding] = [5 - 1 - 2 = 2] on each spatial dimension
  // window_strides = [1,1,1]
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  // feature_group_count = 1
  // batch_group_count = 1

  %conv = "stablehlo.convolution"(%arg2, %kernel_rev2) {
