  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<16x7x11x11x11xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<16x7x11x11x11xf32>

