  // window_dimensions = [1,1,2,2,2] (include batch and channel dims as 1)
  // window_strides = [1,1,2,2,2]
  // padding = 0

  %init_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf

  %maxpool1 = "stablehlo.reduce_window"(%conv_bias, %init_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
