  // stablehlo.reduce removes reduced dims, so we must reshape after to add dim back
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%maxpool2, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
