```mlir
func.func @main(%arg0: tensor<6x1x1xf32>, %arg1: tensor<7x6x4x4xf32>, %arg2: tensor<6xf32>, %arg3: tensor<6x7x7x7xf32>) -> tensor<6x6x15x15xf32> {
  // %arg0 = bias parameter (6x1x1)
  // %arg1 = conv_transpose.weight (7x6x4x4)
  // %arg2 = conv_transpose.bias (6)
  // %arg3 = input (6x7x7x7)

  // Step 1: Perform ConvTranspose2d with stride=2, padding=1, output_padding=1
  // ConvTranspose2d is implemented as a convolution with lhs_dilation=stride and rhs_dilation=1,
  // padding adjusted for output_padding.
  // Given:
  // input shape: [batch=6, in_channels=7, H=7, W=7]
  // weight shape: [in_channels=7, out_channels=6, KH=4, KW=4] in PyTorch
  // But %arg1 shape is [7x6x4x4], so it is (in_channels, out_channels, KH, KW)
  // StableHLO convolution expects kernel shape [out_channels, in_channels/groups, KH, KW]
  // So we must transpose %arg1 from [7,6,4,4] to [6,7,4,4]

  // Transpose %arg1 from [7,6,4,4] to [6,7,4,4]
  %weight_transposed = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Convolution dimension numbers for NCHW:
  // input: [b, f, h, w] = [6,7,7,7]
  // kernel: [o, i, kh, kw] = [6,7,4,4]
  // output: [b, f, h_out, w_out] = [6,6,15,15]
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // lhs_dilation = stride = [2,2]
  // rhs_dilation = [1,1]
  // padding = [[padding_low, padding_high], [padding_low, padding_high]] = [[1,1],[1,1]]
  // output_padding=1 is handled by padding adjustment in transposed conv, but StableHLO convolution does not have output_padding attribute.
  // The formula for output size matches with these parameters.

  %conv = "stablehlo.convolution"(%arg3, %weight_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

  // Step 2: Apply softmax along dim=1 (channel dimension)
  // Softmax = exp(x) / sum(exp(x), dim)
  // Compute exp(%conv)
  %exp_conv = "stablehlo.exponential"(%conv) : (tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Compute sum of exp along dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_conv, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>

  // Broadcast sum_exp back to shape of exp_conv for division
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Divide exp_conv by sum_exp_broadcast to get softmax
  %softmax = stablehlo.divide %exp_conv, %sum_exp_broadcast : tensor<6x6x15x15xf32>

  // Step 3: Add bias %arg0 (6x1x1) to softmax (6x6x15x15)
  // Broadcast %arg0 to (6x6x15x15)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>

  %add_bias = stablehlo.add %softmax, %bias_broadcast : tensor<6x6x15x15xf32>

  // Step 4: Multiply by scaling factor 2.0 (from %arg2)
  // %arg2 is shape (6), but scaling_factor is scalar 2.0 in Python code.
  // The problem states scaling_factor=2.0, but %arg2 is conv_transpose.bias (6xf32).
  // The scaling factor is a constant 2.0, so we create a constant tensor of shape (6x6x15x15) filled with 2.0.
