    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

  // Add bias: broadcast conv_bias from [16] to [6x16x14x5x5]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>
  %bias_bcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<1x16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_bcast_reshaped : tensor<6x16x14x5x5xf32>

  // Multiply by multiplier: broadcast multiplier [16x1x1x1] to [6x16x14x5x5]
  %mult_bcast = "stablehlo.broadcast_in_dim"(%multiplier) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<16x1x1x1xf32>) -> tensor<1x16x1x1x1xf32>
  %mult_bcast_reshaped = "stablehlo.broadcast_in_dim"(%mult_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<1x16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>
