  // InstanceNorm3d: normalize per sample and channel over spatial dims (D,H,W)
  // Compute mean over dims 2,3,4
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%multiplied1, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
