      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>
  // Divide mean by 14*5*5=350
  %divisor = stablehlo.constant dense<350.0> : tensor<f32>
  %mean_normalized = stablehlo.divide %mean, %divisor : tensor<6x16xf32>

