  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_normalized) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>
  %diff = stablehlo.subtract %multiplied1, %mean_bcast : tensor<6x16x14x5x5xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x16x14x5x5xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>
  %var = stablehlo.divide %var_sum, %divisor : tensor<6x16xf32>

