  // Compute rsqrt(variance + epsilon)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<6x16xf32>

  // Normalize: (x - mean) * rsqrt_var
  %rsqrt_var_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>
  %normalized = stablehlo.multiply %diff, %rsqrt_var_bcast : tensor<6x16x14x5x5xf32>

