  %clamp_min = stablehlo.constant dense<-1.0> : tensor<f32>
  %clamp_max = stablehlo.constant dense<1.0> : tensor<f32>
  %clamp_min_bcast = "stablehlo.broadcast_in_dim"(%clamp_min) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // scalar broadcast
  %clamp_max_bcast = "stablehlo.broadcast_in_dim"(%clamp_max) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // scalar broadcast
  %clamped_min = stablehlo.maximum %normalized, %clamp_min_bcast : tensor<6x16x14x5x5xf32>
  %clamped = stablehlo.minimum %clamped_min, %clamp_max_bcast : tensor<6x16x14x5x5xf32>

  // Multiply by multiplier again
  %multiplied2 = stablehlo.multiply %clamped, %mult_bcast_reshaped : tensor<6x16x14x5x5xf32>

  // Max over channel dimension (dim=1)
  %init_min = stablehlo.constant dense<0xFF800000> : tensor<f32> // -inf
  %max = "stablehlo.reduce"(%multiplied2, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max_val : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x14x5x5xf32>

  stablehlo.return %max : tensor<6x14x5x5xf32>
}
