func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
  // Compute max over dimension 1 for numerical stability: max_x[i] = max_j x[i,j]
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%x, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast max_x back to shape 7x8 for subtraction
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Subtract max for numerical stability: x - max_x
  %x_shifted = stablehlo.subtract %x, %max_broadcast : tensor<7x8xf32>

  // Compute exp(x - max_x)
  %exp_shifted = stablehlo.exponential %x_shifted : tensor<7x8xf32>

  // Sum exp(x - max_x) over dimension 1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast sum_exp back to shape 7x8 for division
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Divide exp(x - max_x) by sum_exp to get softmax
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_broadcast : tensor<7x8xf32>

  return %softmax : tensor<7x8xf32>
}
