  // %arg0: conv_transpose.weight (in_channels=3, out_channels=16, kernel=3x3x3)
  // %arg1: conv_transpose.bias (16)
  // %arg2: batch_norm.weight (gamma) (16)
  // %arg3: batch_norm.bias (beta) (16)
  // %arg4: input tensor (batch=6, in_channels=3, 7x7x7)

  // Step 1: ConvTranspose3d (transposed convolution)
  // conv_transpose weight shape: (in_channels=3, out_channels=16, 3,3,3)
  // PyTorch ConvTranspose3d weight shape: (in_channels, out_channels, kD, kH, kW)
  // StableHLO convolution expects lhs: input, rhs: kernel
  // But conv_transpose is a transposed convolution, which can be implemented as a convolution with lhs_dilation and reversed kernel spatial dims.
  // We implement ConvTranspose3d as a convolution with lhs_dilation = stride, rhs_dilation=1, and reversed kernel spatial dims.

  // Reverse kernel spatial dims 2,3,4 (the last 3 dims)
  %rev_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<3x16x3x3x3xf32>

  // Broadcast input to match convolution lhs layout: input is (6x3x7x7x7)
  // Convolution dimension numbers: lhs [b, i, d, h, w], rhs [i, o, kd, kh, kw] -> output [b, o, d, h, w]
  // Our input is (6x3x7x7x7), kernel is (3x16x3x3x3)
  // So dimension_numbers = #stablehlo.conv<[b, i, 2, 3, 4]x[i, o, 2, 3, 4]->[b, o, 2, 3, 4]>
  // lhs_dilation = stride = 2 for each spatial dim
  // rhs_dilation = 1
  // padding = padding=1 for each spatial dim

  %conv = "stablehlo.convolution"(%arg4, %rev_kernel) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
