  %c_subtract = stablehlo.constant dense<0.5> : tensor<f32>
  %c_subtract_tensor = "stablehlo.broadcast_in_dim"(%c_subtract) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub = stablehlo.subtract %conv_bias, %c_subtract_tensor : tensor<6x6x4x4xf32>

  // 4) HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
