  %c_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c_6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c_6_tensor = "stablehlo.broadcast_in_dim"(%c_6) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
