  // output_padding is handled by adjusting padding or output shape, but StableHLO convolution does not have output_padding attribute.
  // We simulate output_padding by adding padding on the right side of input or adjusting padding.
  // PyTorch ConvTranspose3d formula for output shape:
  // output = (input - 1) * stride - 2*padding + kernel + output_padding
  // Here stride=2, padding=1, kernel=3, output_padding=1
  // So output spatial dims = (input_dim -1)*2 - 2*1 + 3 + 1 = 2*input_dim - 2 + 3 +1 -2 = 2*input_dim
  // So output spatial dims are exactly double input dims, so lhs_dilation=2, padding=1 is correct.

  // dimension_numbers: lhs [b, f, d, h, w], rhs [o, i, kd, kh, kw] -> [b, f, d, h, w]
  // feature_group_count=1, batch_group_count=1

  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
