  // %arg1: conv.bias (7)
  // %arg2: bn.weight (gamma) (7)
  // %arg3: bn.bias (beta) (7)
  // %arg4: input tensor (batch=6, in_channels=8, height=6, width=6)

  // Step 1: Convolution
  // conv2d with stride=1, padding=0, dilation=1, groups=1
  %conv = "stablehlo.convolution"(%arg4, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Step 2: Add conv.bias (broadcast bias over batch, height, width)
  // Broadcast conv.bias from [7] to [6x7x4x4]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x4x4xf32>

  // Step 3: BatchNorm (training mode)
  // Compute mean over batch, height, width dims: dims = [0, 2, 3]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%conv_bias, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute divisor = batch_size * height * width = 6*4*4=96.0
  %divisor = stablehlo.constant dense<96.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %divisor : tensor<7xf32>

  // Compute x - mean (broadcast mean to [6x7x4x4])
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %x_centered = stablehlo.subtract %conv_bias, %mean_broadcast : tensor<6x7x4x4xf32>

  // Compute variance: mean of (x - mean)^2 over dims [0,2,3]
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7x4x4xf32>
  %var = "stablehlo.reduce"(%x_centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
  %var_div = stablehlo.divide %var, %divisor : tensor<7xf32>

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_eps = stablehlo.add %var_div, %epsilon : tensor<7xf32>

  // Compute rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) * inv_std
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %x_norm = stablehlo.multiply %x_centered, %inv_std_broadcast : tensor<6x7x4x4xf32>

  // Scale and shift: x_norm * bn.weight + bn.bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7x4x4xf32>

  // Step 4: Multiply by scaling_factor = 2.0 (broadcast scalar)
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_broadcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %final = stablehlo.multiply %bn_out, %scaling_broadcast : tensor<6x7x4x4xf32>

  return %final : tensor<6x7x4x4xf32>
}
