  // %arg1: conv.bias (7)
  // %arg2: bn.weight (gamma) (7)
  // %arg3: bn.bias (beta) (7)
  // %arg4: input tensor (batch=6, in_channels=8, height=6, width=6)

  // Step 1: Convolution
  // conv2d with stride=1, padding=0, dilation=1, groups=1
  %conv = "stablehlo.convolution"(%arg4, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
