  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %x_norm = stablehlo.multiply %x_centered, %inv_std_broadcast : tensor<6x7x4x4xf32>

  // Scale and shift: x_norm * bn.weight + bn.bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7x4x4xf32>

  // Step 4: Multiply by scaling_factor = 2.0 (broadcast scalar)
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_broadcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %final = stablehlo.multiply %bn_out, %scaling_broadcast : tensor<6x7x4x4xf32>

  return %final : tensor<6x7x4x4xf32>
}
