func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = input (6x7)

  // Compute gemm: x @ W^T + b
  // W^T shape: 7x7 -> transpose to 7x7 (same shape, but transpose needed for dot_general)
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: batch dims empty, contracting dims lhs=1, rhs=0
  %t1 = "stablehlo.dot_general"(%arg2, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // add bias: broadcast bias (7) to (6x7)
  %t2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %t3 = stablehlo.add %t1, %t2 : tensor<6x7xf32>

  // max over dim=1, keepdim=True -> result shape (6x1)
  // stablehlo.reduce with maximum over dim=1
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%t3, %c_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast max to (6x1)
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // mean over dim=1, keepdim=True -> shape (6x1)
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%t3, %c_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum_val = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast sum to (6x1)
  %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // divide by 7 (size of dim=1)
  %c_7 = stablehlo.constant dense<7.0> : tensor<f32>
  %c_7_broadcast = "stablehlo.broadcast_in_dim"(%c_7) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %mean = stablehlo.divide %sum_broadcast, %c_7_broadcast : tensor<6x1xf32>

  // subtract mean from max_broadcast
  %sub = stablehlo.subtract %max_broadcast, %mean : tensor<6x1xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>
  %c_sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>  // approx sqrt(2)
  // broadcast constants to (6x1)
  %half_b = "stablehlo.broadcast_in_dim"(%c_half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_b = "stablehlo.broadcast_in_dim"(%c_one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %sqrt2_b = "stablehlo.broadcast_in_dim"(%c_sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>

  // x / sqrt(2)
  %div = stablehlo.divide %sub, %sqrt2_b : tensor<6x1xf32>
  // erf(x / sqrt(2))
  %erf = chlo.erf %div : tensor<6x1xf32> -> tensor<6x1xf32>
  // 1 + erf(...)
  %add = stablehlo.add %one_b, %erf : tensor<6x1xf32>
  // x * 0.5
  %mul1 = stablehlo.multiply %sub, %half_b : tensor<6x1xf32>
  // final gelu = x * 0.5 * (1 + erf(...))
  %gelu = stablehlo.multiply %mul1, %add : tensor<6x1xf32>

  return %gelu : tensor<6x1xf32>
}
