  // %arg0 = weight: tensor<7x7xf32>
  // %arg1 = bias: tensor<7xf32>
  // %arg2 = input: tensor<6x7xf32>

  // Perform matmul: x @ W^T + b
  // Note: PyTorch Linear does x @ W^T + b, so we transpose weight
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul = "stablehlo.dot_general"(%arg2, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Broadcast bias from [7] to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Add bias
  %add_bias = stablehlo.add %matmul, %bias_broadcast : tensor<6x7xf32>

