  %sigmoid = stablehlo.divide %one_broadcast, %exp_plus_one : tensor<6x7xf32>

  // Swish activation: x * sigmoid(x)
  %swish = stablehlo.multiply %add_bias, %sigmoid : tensor<6x7xf32>

  // scaling_factor = 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7xf32>

  // Scale the swish output
  %scaled = stablehlo.multiply %swish, %scale_broadcast : tensor<6x7xf32>

  return %scaled : tensor<6x7xf32>
