  // %arg0 shape: [6,1,1], output shape: [6,6,4,4]
  // broadcast_dimensions = [0, 1, 2] means input dims map to output dims 0,1,2? No, input rank=3, output rank=4
  // We must broadcast %arg0 from [6,1,1] to [6,6,4,4]
  // The input dims correspond to output dims: batch=0, channel=1, spatial=2,3
  // The bias shape is (out_channels,1,1) = (6,1,1), but conv output shape is (6,6,4,4)
