  // %arg2 shape: [6], output shape: [6,6,4,4]
  // %arg2 dims: [feature], output dims: [batch, feature, height, width]
  // So broadcast_dimensions = [1]
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

