func.func @main(%add_value: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: x @ weight^T + bias
  // weight shape: [7,7], input shape: [6,7]
  // We want to do input [6x7] dot weight^T [7x7] -> [6x7]
  // So contract input dim 1 with weight dim 1, batch dims none
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul = "stablehlo.dot_general"(%input, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %add_bias = stablehlo.add %matmul, %bias : tensor<6x7xf32>

  // Add add_value (shape [7]) broadcasted to [6x7]
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%add_value) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add_val = stablehlo.add %add_bias, %add_value_broadcast : tensor<6x7xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x)) = logistic(x)
  %sigmoid = stablehlo.logistic %add_val : tensor<6x7xf32>
  %swish = stablehlo.multiply %add_val, %sigmoid : tensor<6x7xf32>

  // Tanh
  %tanh = stablehlo.tanh %swish : tensor<6x7xf32>

  // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
  %c_sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)
  %c_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%c_sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %x_div_sqrt2 = stablehlo.divide %tanh, %c_sqrt2_broadcast : tensor<6x7xf32>
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x7xf32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %gelu = stablehlo.multiply %tanh, %half_broadcast : tensor<6x7xf32>
  %gelu = stablehlo.multiply %gelu, %one_plus_erf : tensor<6x7xf32>

  // Hardtanh with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %clamp_min = stablehlo.maximum %gelu, %min_val_broadcast : tensor<6x7xf32>
  %hardtanh = stablehlo.minimum %clamp_min, %max_val_broadcast : tensor<6x7xf32>

  return %hardtanh : tensor<6x7xf32>
}
