func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Save original input for residual add
  %original = %input : tensor<6x7xf32>

  // GEMM: x = input @ weight^T + bias
  // weight shape: [7,7], we need weight^T: [7,7], so transpose weight
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general with contracting dims: input: [6x7], weight_t: [7x7]
  // Contract input dim 1 with weight_t dim 0, no batching dims
  %gemm = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: bias shape [7], broadcast to [6x7]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x = stablehlo.add %gemm, %bias_bcast : tensor<6x7xf32>

  // Subtract: x = x - subtract
  // subtract shape [7], broadcast to [6x7]
  %subtract_bcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_sub = stablehlo.subtract %x, %subtract_bcast : tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1 (features), keepdim
  // mean = sum / size
  // sum over dim=1
  %init_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x_sub, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // sum shape: [6], need to keepdim=1 -> [6x1]
  %sum_keepdim = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
  // divide by 7 (size of dim 1)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_bcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %mean = stablehlo.divide %sum_keepdim, %seven_bcast : tensor<6x1xf32>

  // LogSumExp over dim=1, keepdim
  // logsumexp(x) = log(sum(exp(x)))
  // x shape: [6x1], dim=1 size=1, so logsumexp is just log(exp(x)) = x
  // But to follow the formula, do exp, sum, log
  %exp = stablehlo.exponential %mean : tensor<6x1xf32>
  %init_sum2 = stablehlo.constant dense<0.0> : tensor<f32>
