func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
  // InstanceNorm2d with num_features=7, training mode (use batch statistics)
  // Input shape: [N=6, C=7, H=8, W=8]
  // Compute mean and variance per instance per channel over spatial dims (H,W)
  // mean shape: [6,7,1,1], variance shape: [6,7,1,1]

  // Step 1: Compute mean over dims 2 and 3 (H and W)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%arg0, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 2: Divide sum by (H*W) = 64 to get mean
  %c64 = stablehlo.constant dense<64.0> : tensor<f32>
  %mean_reshaped = stablehlo.reshape %mean : tensor<6x7xf32> -> tensor<6x7x1x1xf32>
  %c64_broadcast = "stablehlo.broadcast_in_dim"(%c64) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %mean_f32 = stablehlo.divide %mean_reshaped, %c64_broadcast : tensor<6x7x1x1xf32>

  // Step 3: Compute (x - mean)
  %mean_broadcast = %mean_f32  // already broadcasted to [6,7,1,1]
  %x_minus_mean = stablehlo.subtract %arg0, %mean_broadcast : tensor<6x7x8x8xf32>

  // Step 4: Compute squared difference (x - mean)^2
  %sq_diff = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<6x7x8x8xf32>

  // Step 5: Compute variance = mean of squared differences over dims 2 and 3
  %var_sum = "stablehlo.reduce"(%sq_diff, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  %var_reshaped = stablehlo.reshape %var_sum : tensor<6x7xf32> -> tensor<6x7x1x1xf32>
  %var_f32 = stablehlo.divide %var_reshaped, %c64_broadcast : tensor<6x7x1x1xf32>

  // Step 6: Compute inverse stddev = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-05> : tensor<f32>
  %var_plus_eps = stablehlo.add %var_f32, %eps : tensor<6x7x1x1xf32>
  %stddev = stablehlo.sqrt %var_plus_eps : tensor<6x7x1x1xf32>
  %inv_stddev = stablehlo.divide %c0, %stddev : tensor<6x7x1x1xf32>
  // Note: c0 is zero, so divide by zero is zero, incorrect. Instead use reciprocal:
  // stablehlo.rsqrt(x) = 1 / sqrt(x)
  %inv_stddev = stablehlo.rsqrt %var_plus_eps : tensor<6x7x1x1xf32>

  // Step 7: Normalize: (x - mean) * inv_stddev
  %normalized = stablehlo.multiply %x_minus_mean, %inv_stddev : tensor<6x7x8x8xf32>

  // Step 8: Return normalized output (no affine transform since no weight/bias given)
  stablehlo.return %normalized : tensor<6x7x8x8xf32>
}
