  %0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Actually, %arg0 is 7x7, transpose is 7x7, but we want to multiply input (6x7) by weight^T (7x7)
  // The weight matrix is square, so transpose is still 7x7, but we must do dot_general with contracting dims 1 of lhs and 0 of rhs
  %1 = "stablehlo.dot_general"(%arg2, %0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
