  // Steps:
  // 1) max over dim=1 (for numerical stability)
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %4 = "stablehlo.reduce"(%3, %c_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %5 = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%5) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 2) broadcast max to shape [6x7]
  %6 = "stablehlo.broadcast_in_dim"(%4) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // 3) subtract max for numerical stability
  %7 = stablehlo.subtract %3, %6 : tensor<6x7xf32>
  // 4) exp
  %8 = stablehlo.exponential %7 : tensor<6x7xf32>
  // 5) sum exp over dim=1
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %9 = "stablehlo.reduce"(%8, %c_zero) ({
    ^bb1(%a: tensor<f32>, %b: tensor<f32>):
      %10 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%10) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // 6) log
  %11 = stablehlo.log %9 : tensor<6xf32>
  // 7) add back max
  %12 = stablehlo.add %11, %4 : tensor<6xf32>
