  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16x14x14xf32>
  %denom = stablehlo.add %one_bcast, %exp_neg : tensor<16x16x14x14xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16x14x14xf32>

  // GroupNorm:
  // Reshape (N, C, H, W) = (16,16,14,14) to (N, G, C//G, H, W) = (16,8,2,14,14)
  %reshape1 = stablehlo.reshape %sigmoid : (tensor<16x16x14x14xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute mean over axes [2,3,4]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  // count = 2*14*14 = 392.0
  %count = stablehlo.constant dense<392.0> : tensor<f32>
  %count_bcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x8xf32>
  %mean_val = stablehlo.divide %mean, %count_bcast : tensor<16x8xf32>

  // Broadcast mean to (16x8x2x14x14)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_val) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // (x - mean)
  %diff = stablehlo.subtract %reshape1, %mean_bcast : tensor<16x8x2x14x14xf32>

  // Variance: mean of (x - mean)^2 over axes [2,3,4]
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x8x2x14x14xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>
  %var = stablehlo.divide %var_sum, %count_bcast : tensor<16x8xf32>

  // Add epsilon=1e-5
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x8xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x8xf32>

  // rsqrt(variance + eps)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x8xf32>

  // Broadcast rsqrt_var to (16x8x2x14x14)
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Normalize: (x - mean) * rsqrt_var
  %norm = stablehlo.multiply %diff, %rsqrt_bcast : tensor<16x8x2x14x14xf32>

  // Reshape normalized back to (16x16x14x14)
  %norm_reshaped = stablehlo.reshape %norm : (tensor<16x8x2x14x14xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast group_norm.weight (%arg4 shape 16x1x1) to (16x16x14x14)
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast group_norm.bias (%arg5 shape 16x1x1) to (16x16x14x14)
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg5) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>

  // Apply scale and shift: norm * weight + bias
  %scaled_norm = stablehlo.multiply %norm_reshaped, %gn_weight_bcast : tensor<16x16x14x14xf32>
  %shifted_norm = stablehlo.add %scaled_norm, %gn_bias_bcast : tensor<16x16x14x14xf32>

  stablehlo.return %shifted_norm : tensor<16x16x14x14xf32>
}
