func.func @main(%bias: tensor<7x1x1xf32>, %weight: tensor<7x7x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transposed convolution with stride=2, padding=1, output_padding=1
  // dimension_numbers: input [b, f, h, w] = [6,7,6,6]
  // kernel [o, i, h, w] = [7,7,3,3]
  // output [b, f, h, w] = [6,7,12,12]
  // lhs_dilation = stride = [2,2]
  // rhs_dilation = [1,1]
  // padding = [1,1]
  // output_padding = 1 is handled by padding adjustment in stablehlo by adding 1 to the output size, so we add 1 to the padding high side
  // feature_group_count = 1
  %one = stablehlo.constant dense<1> : tensor<i64>
  %two = stablehlo.constant dense<2> : tensor<i64>
  %zero = stablehlo.constant dense<0> : tensor<i64>

  // lhs_dilation = stride = [2,2]
  %lhs_dilation = stablehlo.constant dense<array<i64: 2, 2>> : tensor<2xi64>
  // rhs_dilation = [1,1]
  %rhs_dilation = stablehlo.constant dense<array<i64: 1, 1>> : tensor<2xi64>
  // window_strides = [1,1] for transposed conv (convolution op is cross-correlation, so stride is 1 here)
  %window_strides = stablehlo.constant dense<array<i64: 1, 1>> : tensor<2xi64>
  // padding = [[1,2],[1,2]] to handle padding=1 and output_padding=1 (high padding is low+output_padding)
  %padding = stablehlo.constant {value = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>} : () -> tensor<2x2xi64>

  // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
  // This is the standard NCHW layout for input and output, OIHW for kernel
  // We encode this as a symbol attribute
  %dim_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>

  %conv = "stablehlo.convolution"(%input, %weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: bias shape is [7x1x1], broadcast to [6x7x12x12]
  // broadcast_in_dim with broadcast_dimensions = [1, 2, 3]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>

  %add_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x12x12xf32>

  // Clamp min=0.0 max=1.0
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>

  %clamp_min = stablehlo.maximum %add_bias, %c0 : tensor<6x7x12x12xf32>
  %clamp = stablehlo.minimum %clamp_min, %c1 : tensor<6x7x12x12xf32>

  // Multiply by scaling_factor=2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scaled = stablehlo.multiply %clamp, %scale : tensor<6x7x12x12xf32>

  // Clamp again min=0.0 max=1.0
  %clamp2_min = stablehlo.maximum %scaled, %c0 : tensor<6x7x12x12xf32>
  %clamp2 = stablehlo.minimum %clamp2_min, %c1 : tensor<6x7x12x12xf32>

  // Divide by scaling_factor=2.0
  %result = stablehlo.divide %clamp2, %scale : tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}
