func.func @main(%ln_weight: tensor<6x7x7xf32>, %ln_bias: tensor<6x7x7xf32>, %x: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  // Compute mean over last 3 dims (1,2,3) of %x: shape (16x6x7x7) -> (16)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute count = 6*7*7 = 294 as constant scalar
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>

  // mean = sum / count
  %mean_div = stablehlo.divide %mean, %c294 : tensor<16xf32>

  // Broadcast mean to shape (16x6x7x7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // x - mean
  %x_centered = stablehlo.subtract %x, %mean_bcast2 : tensor<16x6x7x7xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x6x7x7xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.divide %var_sum, %c294 : tensor<16xf32>

  // Broadcast variance to (16x6x7x7)
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
  %var_bcast2 = "stablehlo.broadcast_in_dim"(%var_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // epsilon constant for numerical stability
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<1xf32>
  // Broadcast epsilon to (16x6x7x7)
  %epsilon_bcast1 = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>
  %epsilon_bcast2 = "stablehlo.broadcast_in_dim"(%epsilon_bcast1) {broadcast_dimensions = array<i64: 0, 1, 2, 3} : (tensor<16xf32>) -> tensor<16x6x7x7xf32>

  // var + epsilon
  %var_eps = stablehlo.add %var_bcast2, %epsilon_bcast2 : tensor<16x6x7x7xf32>

  // rsqrt(var + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x6x7x7xf32>

  // Broadcast ln.weight and ln.bias from (6x7x7) to (16x6x7x7)
  %ln_weight_bcast = "stablehlo.broadcast_in_dim"(%ln_weight) {broadcast_dimensions = array<i64: 1, 2, 3} : (tensor<6x7x7xf32>) -> tensor<1x6x7x7xf32>
  %ln_weight_bcast2 = "stablehlo.broadcast_in_dim"(%ln_weight_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3} : (tensor<1x6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %ln_bias_bcast = "stablehlo.broadcast_in_dim"(%ln_bias) {broadcast_dimensions = array<i64: 1, 2, 3} : (tensor<6x7x7xf32>) -> tensor<1x6x7x7xf32>
  %ln_bias_bcast2 = "stablehlo.broadcast_in_dim"(%ln_bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3} : (tensor<1x6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // normalized = (x - mean) * inv_std
  %normalized = stablehlo.multiply %x_centered, %inv_std : tensor<16x6x7x7xf32>

  // output = normalized * weight + bias
  %scaled = stablehlo.multiply %normalized, %ln_weight_bcast2 : tensor<16x6x7x7xf32>
  %output = stablehlo.add %scaled, %ln_bias_bcast2 : tensor<16x6x7x7xf32>

  return %output : tensor<16x6x7x7xf32>
}
