  // stablehlo.convolution with lhs_dilation=stride, rhs_dilation=1, padding adjusted for output_padding
  // dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  // feature_group_count=1, batch_group_count=1

  // Calculate padding for convolution:
  // For transposed conv, padding attribute is:
  // padding = [[padding_lo, padding_hi], ...] where
  // padding_lo = kernel_size - 1 - padding
  // padding_hi = output_padding
  // kernel_size=3, padding=1, output_padding=1
  // So padding_lo = 3 - 1 - 1 = 1
  // padding_hi = 1
  // So padding = [[1,1], [1,1]]

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
