  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_bias, %tanh_softplus : tensor<6x7x12x12xf32>

  // Step 4: Add add_value = 0.5 (broadcast scalar)
  %add_value = stablehlo.constant dense<0.5> : tensor<f32>
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%add_value) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus = stablehlo.add %mish, %add_value_broadcast : tensor<6x7x12x12xf32>

  // Step 5: Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_val_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_val_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp_min = stablehlo.maximum %mish_plus, %min_val_broadcast : tensor<6x7x12x12xf32>
  %hardtanh = stablehlo.minimum %clamp_min, %max_val_broadcast : tensor<6x7x12x12xf32>

  // Step 6: Scale output by scale=2 (broadcast scalar)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  // Return final output
  return %scaled : tensor<6x7x12x12xf32>
}
