  %c0 = stablehlo.constant dense<0> : tensor<i32>
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>
  %c0f = stablehlo.constant dense<0.0> : tensor<f32>

  // Broadcast idx from shape [4] to [4x8] along dimension 0
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<4xi32>) -> tensor<4x8xi32>

  // Create iota for channel dimension c: shape [8]
  %iota_c = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast iota_c from [8] to [4x8] along dimension 1
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota_c) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<4x8xi32>

  // Compare idx_bcast == iota_bcast, result is i1 tensor<4x8xi1>
  %eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

  // Check idx in range 0 <= idx < 8
  %ge0 = "stablehlo.compare"(%idx, %c0) {comparison_direction = #stablehlo<comparison_direction GE>} : (tensor<4xi32>, tensor<i32>) -> tensor<4xi1>
  %lt8 = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>} : (tensor<4xi32>, tensor<i32>) -> tensor<4xi1>
  // Logical AND of ge0 and lt8 to get in_range mask [4xi1]
  %in_range = "stablehlo.and"(%ge0, %lt8) : (tensor<4xi1>, tensor<4xi1>) -> tensor<4xi1>

  // Broadcast in_range from [4] to [4x8] along dimension 0
  %in_range_bcast = "stablehlo.broadcast_in_dim"(%in_range) {broadcast_dimensions = array<i64: 0>} : (tensor<4xi1>) -> tensor<4x8xi1>

  // Combine eq and in_range_bcast: final mask = eq AND in_range_bcast
  %final_mask = "stablehlo.and"(%eq, %in_range_bcast) : (tensor<4x8xi1>, tensor<4x8xi1>) -> tensor<4x8xi1>

  // Select 1.0 where final_mask true else 0.0
  %out = "stablehlo.select"(%final_mask, %c1f, %c0f) : (tensor<4x8xi1>, tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>

  return %out : tensor<4x8xf32>
