func.func @main(%arg0: tensor<7x6x4x4xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x7x7xf32>) -> tensor<6x6x16x16xf32> {
  // Transpose conv_transpose.weight from (in_channels=7, out_channels=6, 4,4) to (out_channels=6, in_channels=7, 4,4)
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c3 = stablehlo.constant dense<3> : tensor<i64>
  %c_perm = stablehlo.constant dense<[1, 0, 2, 3]> : tensor<4xi64>
  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Prepare convolution parameters for transposed convolution
  // conv_transpose is a ConvTranspose2d with stride=2, kernel=4, padding=0 (default)
  // We implement transposed convolution as a convolution with lhs_dilation=stride and rhs_dilation=1
  // Input: %arg2 tensor<6x7x7x7xf32> (NCHW: batch=6, channels=7, H=7, W=7)
  // Kernel: %weight_transposed tensor<6x7x4x4xf32> (out_channels=6, in_channels=7, KH=4, KW=4)
  // Output: tensor<6x6x16x16xf32> (batch=6, channels=6, H_out=16, W_out=16)
  // dimension_numbers: input [b, f, 0, 1], kernel [o, i, 0, 1], output [b, f, 0, 1]
  // window_strides = [1,1] (no stride in convolution, dilation handles stride)
  // lhs_dilation = [2,2] (stride)
  // rhs_dilation = [1,1]
  // padding = [[0,0],[0,0]] (no padding)
  %conv = "stablehlo.convolution"(%arg2, %weight_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x16x16xf32>

  // Add bias: %arg1 is tensor<6xf32>, need to broadcast to output shape tensor<6x6x16x16xf32>
  // Broadcast bias on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x16x16xf32>
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x16x16xf32>

  // Add constant 0.5 (add_value)
  %c_add_value = stablehlo.constant dense<0.5> : tensor<f32>
  %c_add_value_broadcast = "stablehlo.broadcast_in_dim"(%c_add_value) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %add_const = stablehlo.add %add_bias, %c_add_value_broadcast : tensor<6x6x16x16xf32>

  // Minimum with 0.0 (clamp max to 0.0)
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %c_zero_broadcast = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %min0 = stablehlo.minimum %add_const, %c_zero_broadcast : tensor<6x6x16x16xf32>

  // GELU activation: gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %c_sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)
  %c_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%c_sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %x_div_sqrt2 = stablehlo.divide %min0, %c_sqrt2_broadcast : tensor<6x6x16x16xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x6x16x16xf32> -> tensor<6x6x16x16xf32>

  // 1 + erf(...)
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>
  %c_one_broadcast = "stablehlo.broadcast_in_dim"(%c_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %one_plus_erf = stablehlo.add %c_one_broadcast, %erf : tensor<6x6x16x16xf32>

  // 0.5 * x
  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_half_broadcast = "stablehlo.broadcast_in_dim"(%c_half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %half_x = stablehlo.multiply %c_half_broadcast, %min0 : tensor<6x6x16x16xf32>

  // gelu = 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x6x16x16xf32>

  // Multiply by 2.0 (multiply_value)
  %c_mul_value = stablehlo.constant dense<2.0> : tensor<f32>
  %c_mul_value_broadcast = "stablehlo.broadcast_in_dim"(%c_mul_value) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %result = stablehlo.multiply %gelu, %c_mul_value_broadcast : tensor<6x6x16x16xf32>

  return %result : tensor<6x6x16x16xf32>
}

