func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.000000e+00> : tensor<f32>

  // Broadcast c1 to tensor<6x6xf32> for comparison
  %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>

  // mask = abs_diff < 1.0
  %mask = "stablehlo.compare"(%abs_diff, %c1_bcast) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute squared term: 0.5 * diff^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %c05 = stablehlo.constant dense<5.000000e-01> : tensor<f32>
  %c05_bcast = "stablehlo.broadcast_in_dim"(%c05) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %sq_term = stablehlo.multiply %c05_bcast, %diff_sq : tensor<6x6xf32>

  // Compute linear term: abs_diff - 0.5
  %c05_bcast_2 = %c05_bcast
  %lin_term = stablehlo.subtract %abs_diff, %c05_bcast_2 : tensor<6x6xf32>

  // Select smooth_l1 element-wise: if mask then sq_term else lin_term
  %smooth_l1 = "stablehlo.select"(%mask, %sq_term, %lin_term) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements of smooth_l1: reduce over dims 0 and 1
  %init = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %sum = "stablehlo.reduce"(%smooth_l1, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean = sum / 36.0 (6*6)
  %c36 = stablehlo.constant dense<3.600000e+01> : tensor<f32>
  %mean = stablehlo.divide %sum, %c36 : tensor<f32>

  "stablehlo.return"(%mean) : tensor<f32>
}
