func.func @main(%gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
  // Constants for float zero and one
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>

  // Shapes and sizes as constants
  // batch_size=14, channels=16, dim1=16, dim2=16
  // num_groups=8, channels_per_group=2
  %cst_8 = stablehlo.constant dense<8> : tensor<i64>
  %cst_2 = stablehlo.constant dense<2> : tensor<i64>
  %cst_14 = stablehlo.constant dense<14> : tensor<i64>
  %cst_16 = stablehlo.constant dense<16> : tensor<i64>
  %cst_256 = stablehlo.constant dense<256> : tensor<i64>  // 16*16

  // Reshape input from [14,16,16,16] to [14,8,2,16,16]
  %reshape1 = stablehlo.reshape %input : (tensor<14x16x16x16xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute mean over axes [2,3,4] (channels_per_group and spatial dims)
  // Init value for mean is 0.0f
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute mean by dividing sum by 512 (2*16*16)
  %cst_512 = stablehlo.constant dense<512.0> : tensor<f32>
  %mean_scaled = stablehlo.divide %mean, %cst_512 : tensor<14x8xf32>

  // Broadcast mean_scaled to shape [14,8,2,16,16]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<14x8xf32>) -> tensor<14x8x1x1xf32>
  // Need to broadcast to [14,8,2,16,16], so broadcast dims for input rank 2 to output rank 5:
  // mean_scaled shape: [14,8]
  // broadcast_dimensions = [0,1], then broadcast dims 2,3,4 are broadcasted
  %mean_bcast_full = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<14x8xf32>) -> tensor<14x8x1x1xf32>
  // Now broadcast to [14,8,2,16,16] by broadcasting dims 2,3,4
  %mean_bcast_2 = "stablehlo.broadcast_in_dim"(%mean_bcast_full) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %reshape1, %mean_bcast_2 : tensor<14x8x2x16x16xf32>

  // Compute squared difference (x - mean)^2
  %sq_diff = stablehlo.multiply %x_centered, %x_centered : tensor<14x8x2x16x16xf32>

  // Compute variance sum over axes [2,3,4]
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%sq_diff, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute variance by dividing by 512
  %var = stablehlo.divide %var_sum, %cst_512 : tensor<14x8xf32>

  // Add epsilon for numerical stability: var + eps
  %var_eps = stablehlo.add %var, %cst_eps : tensor<14x8xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<14x8xf32>

  // Broadcast inv_std to [14,8,2,16,16]
  %inv_std_bcast_1 = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<14x8xf32>) -> tensor<14x8x1x1xf32>
  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std_bcast_1) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<14x8x1x1xf32>) -> tensor<14x8x2x16x16xf32>

  // Normalize: (x - mean) * inv_std
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast : tensor<14x8x2x16x16xf32>

  // Reshape normalized back to [14,16,16,16]
  %x_norm_reshaped = stablehlo.reshape %x_norm : (tensor<14x8x2x16x16xf32>) -> tensor<14x16x16x16xf32>

  // Reshape gn.weight and gn.bias from [16] to [1,16,1,1] for broadcasting
  %gn_weight_reshaped = stablehlo.reshape %gn_weight : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %gn_bias_reshaped = stablehlo.reshape %gn_bias : (tensor<16xf32>) -> tensor<1x16x1x1xf32>

  // Broadcast gn.weight and gn.bias to [14,16,16,16]
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped) {broadcast_dimensions = array<i64: 1>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias_reshaped) {broadcast_dimensions = array<i64: 1>} : (tensor<1x16x1x1xf32>) -> tensor<14x16x16x16xf32>

  // Apply scale and bias: y = x_norm * weight + bias
  %scaled = stablehlo.multiply %x_norm_reshaped, %gn_weight_bcast : tensor<14x16x16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<14x16x16x16xf32>

  // Return output
  return %shifted : tensor<14x16x16x16xf32>
}
