  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast2 : tensor<16x16xf32>

