  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %clamped_min = stablehlo.maximum %shifted, %min_broadcast : tensor<16x16xf32>
  %clamped = stablehlo.minimum %clamped_min, %max_broadcast : tensor<16x16xf32>

