  // input: NCHW = [6,8,8,8]
  // kernel: OIHW = [7,8,3,3]
  // output: NCHW = [6,7,6,6] because:
  // output_h = floor((8 - 3)/1) + 1 = 6
  // output_w = floor((8 - 3)/1) + 1 = 6
  // stride=1, padding=0, dilation=1

  // Perform convolution
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Broadcast bias %arg1 from [7] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  // Add bias
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Create constants for subtract_value_1=0.5 and subtract_value_2=0.2 as scalars
  %c_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
  %c_sub2 = stablehlo.constant dense<0.2> : tensor<f32>

  // Broadcast subtract_value_1 to [6x7x6x6]
  %sub1_broadcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  // Broadcast subtract_value_2 to [6x7x6x6]
  %sub2_broadcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>

  // Subtract subtract_value_1
  %sub1 = stablehlo.subtract %add_bias, %sub1_broadcast : tensor<6x7x6x6xf32>
  // Subtract subtract_value_2
  %sub2 = stablehlo.subtract %sub1, %sub2_broadcast : tensor<6x7x6x6xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log_plus_one(exp(x))
  %exp = stablehlo.exponential %sub2 : tensor<6x7x6x6xf32>
  %softplus = stablehlo.log_plus_one %exp : tensor<6x7x6x6xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x6x6xf32>
  %mish = stablehlo.multiply %sub2, %tanh_softplus : tensor<6x7x6x6xf32>

  return %mish : tensor<6x7x6x6xf32>
}
