func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Convert targets from i64 to f32 for indexing mask creation
  %tgt_f32 = stablehlo.convert %arg1 : (tensor<6xi64>) -> tensor<6xf32>

  // Create iota for class indices: shape (7), values 0..6
  %class_iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<7xi32>
  // Convert class_iota to f32 for comparison
  %class_iota_f32 = stablehlo.convert %class_iota : (tensor<7xi32>) -> tensor<7xf32>

  // Broadcast targets to shape (6x7) for comparison
  %tgt_bcast = "stablehlo.broadcast_in_dim"(%tgt_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Broadcast class indices to shape (6x7)
  %class_bcast = "stablehlo.broadcast_in_dim"(%class_iota_f32) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Compare equality: (targets == class indices) -> i1 mask
  %eq_mask = "stablehlo.compare"(%tgt_bcast, %class_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>} : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xi1>

  // Convert mask i1 to f32 (true=1.0, false=0.0)
  %eq_mask_f32 = stablehlo.convert %eq_mask : (tensor<6x7xi1>) -> tensor<6x7xf32>

  // Compute log softmax:
  // Step 1: max logits per batch for numerical stability
  %init_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %init_neg_inf_vec = "stablehlo.broadcast_in_dim"(%init_neg_inf) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32> // will be replaced below

  // Reduce max over classes (dim=1)
  %init_neg_inf_scalar = stablehlo.constant dense<0xFF800000> : tensor<f32>
  %max_logits = "stablehlo.reduce"(%arg0, %init_neg_inf_scalar) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast max_logits to shape (6x7)
  %max_logits_bcast = "stablehlo.broadcast_in_dim"(%max_logits) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Subtract max_logits from logits
  %logits_stable = stablehlo.subtract %arg0, %max_logits_bcast : tensor<6x7xf32>

  // Exponentiate stabilized logits
  %exp_logits = stablehlo.exponential %logits_stable : tensor<6x7xf32>

  // Sum exp_logits over classes (dim=1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_logits, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Log of sum_exp
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6xf32>

  // Broadcast log_sum_exp to shape (6x7)
  %log_sum_exp_bcast = "stablehlo.broadcast_in_dim"(%log_sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Compute log softmax: logits_stable - log_sum_exp_bcast
  %log_softmax = stablehlo.subtract %logits_stable, %log_sum_exp_bcast : tensor<6x7xf32>

  // Select log probabilities of the target classes by multiplying with mask and summing over classes
  %masked_log_softmax = stablehlo.multiply %log_softmax, %eq_mask_f32 : tensor<6x7xf32>

  // Sum over classes (dim=1) to get log prob of correct class per batch
  %log_prob = "stablehlo.reduce"(%masked_log_softmax, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Negate log_prob to get per-example loss
  %neg_log_prob = stablehlo.negate %log_prob : tensor<6xf32>

  // Sum over batch (dim=0) to get total loss
  %loss = "stablehlo.reduce"(%neg_log_prob, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean loss by dividing by batch size (6)
  %batch_size = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_loss = stablehlo.divide %loss, %batch_size : tensor<f32>

  return %mean_loss : tensor<f32>
}
