func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight (7x7)
  // %arg1 = gemm.bias (7)
  // %arg2 = input (6x7)

  // Compute gemm: x = dot_general(%arg2, %arg0) + %arg1
  // dot_general with contracting dims: input's dim 1 and weight's dim 0
  // Result shape: (6x7)
  %dot = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Broadcast bias %arg1 (7) to (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Add bias
  %x = stablehlo.add %dot, %bias_bcast : tensor<6x7xf32>

  // Save original_x for residual add
  %original_x = %x

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x : tensor<6x7xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_exp = stablehlo.add %one_tensor, %exp_neg_x : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_tensor, %one_plus_exp : tensor<6x7xf32>

  // Multiply by scaling_factor = 2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_tensor = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %sigmoid, %scale_tensor : tensor<6x7xf32>

  // Add residual: scaled + original_x
  %result = stablehlo.add %scaled, %original_x : tensor<6x7xf32>

  return %result : tensor<6x7xf32>
}
