func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // %arg0 = conv.weight: [6,7,3,3]
  // %arg1 = conv.bias: [6]
  // %arg2 = input: [6,7,6,6]

  // Step 1: convolution
  // conv dimension numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  // window_strides = [1,1], padding = 0, lhs_dilation = 1, rhs_dilation = 1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Step 2: add bias (broadcast bias from [6] to [6x6x4x4])
  // Broadcast bias on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Step 3: InstanceNorm2d forward (training mode)
  // InstanceNorm2d normalizes per-sample per-channel over spatial dims (2,3)
  // Compute mean over dims 2,3
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%conv_bias, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute divisor = 1/(4*4) = 1/16 = 0.0625
  %const_16 = stablehlo.constant dense<16.0> : tensor<f32>
  %const_1 = stablehlo.constant dense<1.0> : tensor<f32>
  %inv_16 = stablehlo.divide %const_1, %const_16 : tensor<f32>
  // Broadcast inv_16 to mean shape [6x6]
  // Actually scalar to [6x6] by broadcast_in_dim with dims [0,1]
  %inv_16_bcast = "stablehlo.broadcast_in_dim"(%inv_16) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32>
  // But stablehlo.broadcast_in_dim requires operand rank 0 and result rank 2, so broadcast_dimensions = [0,1]
  %inv_16_bcast = "stablehlo.broadcast_in_dim"(%inv_16) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x6xf32>

  // mean = sum / 16
  %mean_scaled = stablehlo.multiply %mean, %inv_16_bcast : tensor<6x6xf32>

  // Step 4: compute variance
  // variance = mean((x - mean)^2) over dims 2,3
  // First broadcast mean_scaled to conv_bias shape [6x6x4x4]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // x - mean
  %diff = stablehlo.subtract %conv_bias, %mean_bcast : tensor<6x6x4x4xf32>

  // (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6x4x4xf32>

  // reduce sum of diff_sq over dims 2,3
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // variance = var_sum / 16
  %variance = stablehlo.multiply %var_sum, %inv_16_bcast : tensor<6x6xf32>

  // Step 5: normalize: (x - mean) / sqrt(variance + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  // variance + eps
  %var_eps = stablehlo.add %variance, %eps : tensor<6x6xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // broadcast stddev to [6x6x4x4]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // normalized = diff / stddev_bcast
  %normalized = stablehlo.divide %diff, %stddev_bcast : tensor<6x6x4x4xf32>

  // Step 6: divide by constant divide_by = 2.0
  %const_divide_by = stablehlo.constant dense<2.0> : tensor<f32>
  // broadcast scalar to [6x6x4x4]
  %divide_by_bcast = "stablehlo.broadcast_in_dim"(%const_divide_by) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  // broadcast_dimensions = [ ] for scalar to scalar? No, result shape is 4D, operand rank 0, so broadcast_dimensions = []
  // But must specify broadcast_dimensions with length equal to operand rank (0), so empty array is valid
  %divide_by_bcast = "stablehlo.broadcast_in_dim"(%const_divide_by) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>

  // Actually, stablehlo.broadcast_in_dim requires broadcast_dimensions length == operand rank (0), so empty array is correct
  // But result shape must be specified in the type, so we must cast the constant to tensor<6x6x4x4xf32> by broadcast_in_dim

  // normalized / divide_by
  %output = stablehlo.divide %normalized, %divide_by_bcast : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}
