func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x4x4xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x8x8xf32>) -> tensor<6x7x17x17xf32> {
  // %arg0 = bias parameter (7x1x1)
  // %arg1 = conv_transpose.weight (7x7x4x4)
  // %arg2 = conv_transpose.bias (7)
  // %arg3 = input (6x7x8x8)

  // Step 1: Add bias %arg2 to input %arg3 before convolution (to emulate PyTorch ConvTranspose2d bias addition)
  // Broadcast %arg2 from [7] to [6x7x8x8]
  %bcast_bias = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x1x1xf32>
  // Broadcast again to spatial dims 8x8
  %bcast_bias2 = "stablehlo.broadcast_in_dim"(%bcast_bias) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>
  // Add bias to input
  %biased_input = stablehlo.add %arg3, %bcast_bias2 : tensor<6x7x8x8xf32>

  // Step 2: Perform transposed convolution using stablehlo.convolution with lhs_dilation=2 (stride=2)
  // dimension_numbers: input [b, f, 0, 1] = [6,7,8,8]
  // kernel [o, i, 0, 1] = [7,7,4,4]
  // output [b, f, 0, 1] = [6,7,17,17]
  // lhs_dilation = [2,2] to emulate stride=2 transposed conv
  // rhs_dilation = [1,1]
  // padding = [[1,1],[1,1]]
  // feature_group_count = 1
  %conv = "stablehlo.convolution"(%biased_input, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x8x8xf32>, tensor<7x7x4x4xf32>) -> tensor<6x7x17x17xf32>

  // Step 3: Subtract bias %arg0 (7x1x1) from conv output (6x7x17x17)
  // Broadcast %arg0 from [7x1x1] to [6x7x17x17]
  %bcast_bias3 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x1x1xf32>
  %bcast_bias4 = "stablehlo.broadcast_in_dim"(%bcast_bias3) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x17x17xf32>
  %sub = stablehlo.subtract %conv, %bcast_bias4 : tensor<6x7x17x17xf32>

  // Step 4: Apply tanh activation
  %tanh = stablehlo.tanh %sub : tensor<6x7x17x17xf32>

  return %tanh : tensor<6x7x17x17xf32>
}
